var HANGMAN_WORDS=['puzzle','garden','rocket','dolphin','mountain','whisper','crystal','thunder','blanket','journey','octopus','velvet','marble','frozen','glimmer','phoenix','cactus','breeze','lantern','mystery'];
function pickWord(){ return HANGMAN_WORDS[Math.floor(Math.random()*HANGMAN_WORDS.length)]; }
function reveal(word, guessed){ return word.split('').map(function(c){ return guessed.indexOf(c)>=0? c : '_'; }).join(' '); }
function status(word, guessed, wrong){ if(word.split('').every(function(c){return guessed.indexOf(c)>=0;})) return 'win'; if(wrong>=6) return 'lose'; return 'playing'; }
var EXPORTS={pickWord:pickWord,reveal:reveal,status:status,HANGMAN_WORDS:HANGMAN_WORDS};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HangmanForgePure = EXPORTS; }
